insert into public.mountains
  (id, name, name_hanja, province, region, elevation_m, categories, difficulty, summary, description, best_season, data_source, verified) values
  ('seoraksan', '설악산', '雪嶽山', '강원 속초·양양·인제', '강원', 1708, ARRAY['국립공원', '암릉', '조망', '단풍', '설경', '일출']::text[], '최상', '화강암 암봉과 깊은 계곡이 함께 있는 한국 산악미의 기준점.', '설악산은 백두대간이 동해로 내리뻗다가 솟구친 곳으로, 최고봉 대청봉의 표고는 1,708m다. 남한에서 한라산과 지리산 다음으로 높다. 능선을 경계로 서쪽의 내설악과 동쪽의 외설악으로 나뉘며, 두 지역의 인상이 크게 다르다. 외설악은 울산바위와 천불동계곡처럼 화강암이 그대로 드러난 절경이 이어지고, 내설악은 백담사와 수렴동계곡을 따라 물길과 숲이 깊다.
